        protected override void Seed(eParty.Models.AppDbContext context)
        {
            System.Diagnostics.Debug.WriteLine("--- Starting Seed Method ---");

            // --- 1. Tạo Roles nếu chưa có ---
            var roleManager = new RoleManager<IdentityRole>(new RoleStore<IdentityRole>(context));
            if (!roleManager.RoleExists("Admin")) roleManager.Create(new IdentityRole { Name = "Admin" });
            if (!roleManager.RoleExists("Staff")) roleManager.Create(new IdentityRole { Name = "Staff" });
            if (!roleManager.RoleExists("User")) roleManager.Create(new IdentityRole { Name = "User" });
            System.Diagnostics.Debug.WriteLine("Roles checked/created.");

            // --- 2. Tạo User Manager ---
            var userManager = new UserManager<ApplicationUser>(new UserStore<ApplicationUser>(context));
            userManager.PasswordValidator = new PasswordValidator
            {
                RequiredLength = 6,
                RequireNonLetterOrDigit = true,
                RequireDigit = true,
                RequireLowercase = true,
                RequireUppercase = true,
            };
            string defaultPassword = "Pass@123";
            System.Diagnostics.Debug.WriteLine("UserManager configured.");

            // --- 3. Tạo Users với Avatar ---
            CreateUserWithRole(context, userManager, "admin@eparty.com", defaultPassword, "Admin", "Admin", "Account", "0901112222", 20000000, admin);
            CreateUserWithRole(context, userManager, "staff1@eparty.com", defaultPassword, "Staff", "Staff", "01", "0912345678", 8000000, staffone);
            CreateUserWithRole(context, userManager, "staff2@eparty.com", defaultPassword, "Staff", "Staff", "02", "0912345679", 7500000, stafftwo);
            CreateUserWithRole(context, userManager, "user@eparty.com", defaultPassword, "User", "Normal", "User", "0987654321", null, userone);
            // Dữ liệu mới
            CreateUserWithRole(context, userManager, "staff3@eparty.com", defaultPassword, "Staff", "Staff", "03", "0911112222", 7000000, staffthree);
            CreateUserWithRole(context, userManager, "user2@eparty.com", defaultPassword, "User", "Second", "User", "0922223333", null, usertwo);

