            if (rauId > 0) context.Providers.AddOrUpdate(p => p.Name, new Provider { Ingredient = rauId, Name = "Nông Trại Rau Sạch Đà Lạt", PhoneNumber = "0976543210", Address = "101 Đường KLM, Đà Lạt", Cost = 30000 });
