            if (cuaId > 0) context.Providers.AddOrUpdate(p => p.Name, new Provider { Ingredient = cuaId, Name = "Cua Cà Mau", PhoneNumber = "0907778888", Address = "Chợ Bến Thành", Cost = 450000 });
