            // Dữ liệu mới
            int supId = context.Categories.FirstOrDefault(c => c.Name == "Súp")?.Id ?? 0;
            int nuongId = context.Categories.FirstOrDefault(c => c.Name == "Món Nướng")?.Id ?? 0;
            int chayId = context.Categories.FirstOrDefault(c => c.Name == "Món Chay")?.Id ?? 0;

            if (khaiViId > 0) context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = khaiViId, Name = "Gỏi cuốn tôm thịt", Description = "Gỏi cuốn tươi ngon", Unit = 1, Cost = 15000, Image = goicuon });
