            if (lauId > 0) context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = lauId, Name = "Lẩu Thái hải sản", Description = "Lẩu chua cay đặc trưng Thái Lan", Unit = 1, Cost = 350000, Image = lauthai });
