                context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = doUongId, Name = "Coca Cola", Description = "Nước ngọt có gas", Unit = 1, Cost = 15000, Image = cola });
                context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = doUongId, Name = "Bia Tiger", Description = "Bia lon", Unit = 1, Cost = 20000, Image = bia });
            }
            // Dữ liệu mới
            if (supId > 0) context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = supId, Name = "Súp Cua", Description = "Súp cua khai vị", Unit = 1, Cost = 35000, Image = supcua }); // Dùng tạm ảnh
