            if (khaiViId > 0) context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = khaiViId, Name = "Khoai tây chiên", Description = "Khoai tây chiên bơ", Unit = 1, Cost = 45000, Image = khoaitaychien }); // Dùng tạm ảnh
            if (chayId > 0) context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = chayId, Name = "Đậu hũ chiên sả", Description = "Đậu hũ non chiên sả ớt", Unit = 1, Cost = 60000, Image = dauhuchien }); // Dùng tạm ảnh
            if (chayId > 0) context.Foods.AddOrUpdate(f => f.Name, new Food { CategoryId = chayId, Name = "Gỏi cuốn chay", Description = "Gỏi cuốn rau nấm", Unit = 1, Cost = 12000, Image = goicuonchay }); // Dùng tạm ảnh


            SaveChangesWithLogging(context, "Foods");

            // --- 10. Seed FoodIngredients ---
            int goiCuonId = context.Foods.FirstOrDefault(f => f.Name == "Gỏi cuốn tôm thịt")?.Id ?? 0;
            int suonNuongId = context.Foods.FirstOrDefault(f => f.Name == "Sườn non nướng mật ong")?.Id ?? 0;
            int gaHapId = context.Foods.FirstOrDefault(f => f.Name == "Gà hấp lá chanh")?.Id ?? 0;
            int tomNuongId = context.Foods.FirstOrDefault(f => f.Name == "Tôm sú nướng muối ớt")?.Id ?? 0;
            int bunId = context.Ingredients.FirstOrDefault(i => i.Name == "Bún tươi")?.Id ?? 0;
            // Lấy lại các ID ingredient cần thiết
            thitHeoId = context.Ingredients.FirstOrDefault(i => i.Name == "Thịt heo ba rọi")?.Id ?? 0;
            thitGaId = context.Ingredients.FirstOrDefault(i => i.Name == "Thịt gà ta")?.Id ?? 0;
            tomSuId = context.Ingredients.FirstOrDefault(i => i.Name == "Tôm sú")?.Id ?? 0;
            rauId = context.Ingredients.FirstOrDefault(i => i.Name == "Rau xà lách")?.Id ?? 0;
            // Dữ liệu mới
            int supCuaId = context.Foods.FirstOrDefault(f => f.Name == "Súp Cua")?.Id ?? 0;
