            }
            if (suonNuongId > 0 && thitHeoId > 0)
            {
                context.FoodIngredients.AddOrUpdate(fi => new { fi.Food, fi.Ingredient }, new FoodIngredient { Food = suonNuongId, Ingredient = thitHeoId, Amount = 500 });
            }
            if (gaHapId > 0 && thitGaId > 0)
            {
                context.FoodIngredients.AddOrUpdate(fi => new { fi.Food, fi.Ingredient }, new FoodIngredient { Food = gaHapId, Ingredient = thitGaId, Amount = 1000 });
            }
            if (tomNuongId > 0 && tomSuId > 0)
            {
                context.FoodIngredients.AddOrUpdate(fi => new { fi.Food, fi.Ingredient }, new FoodIngredient { Food = tomNuongId, Ingredient = tomSuId, Amount = 300 });
            }
